newgroup="" if getent group "0" >/dev/null 2>&1; then newgroup="0" fi
if [[ -z "${newgroup}" ]]; then >&2 echo "0 is not a defined group on the system" else find -P /etc/issue.d/ -type f ! -group 0 -regextype posix-extended -regex '^.*$' -exec chgrp --no-dereference "$newgroup" {} \;
fi

# Remediation is applicable only in certain platforms if rpm --quiet -q pam_apparmor; then
while IFS= read -r -d '' link; do target=$(readlink -f "$link") cp -p --remove-destination "$target" "$link" done < <(find /etc/pam.d/ -type l -iname "common-*" -print0)
else >&2 echo 'Remediation is not applicable, nothing was done' fi

